      ],
      "support_status": "SUFFICIENT",
      "rationale": "P031 explicitly supplies the condition and retention decision; P009 identifies the original concurrency setting."
    }
  },
  "signal_basis": {
    "component_id": "C036.signal_basis",
    "value": "The bounded test of reduced concurrency produces inconclusive results under the predeclared observation duration and precision requirement; insufficient evidence within the safety window is reported as uncertainty.",
    "scope": "Assessment of the tested concurrency change within its bounded observation and safety window.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
